   synth=createSynthAudio({contextFactory:audio,ownsContext:false,getSettings:()=>({muted:DB.settings.muted,volume:DB.settings.sound/100*.1})});$('#lbLoading').hidden=true;for(const id of ['lbSettings','lbHelp','lbPause'])$('#'+id).disabled=false;$('#lbRenderer').textContent=graphics.caps.renderer+' · '+graphics.settings.label;$('#lbAreaTitle').textContent=areaName();$('#lbCanvas').setAttribute('aria-label','Project Limit Break · '+areaName());$('#lbMap').setAttribute('aria-label',areaName()+' objectives and collision map');$('#lbLoad').hidden=mode==='suite'||model.zoneId!=='chaos';$('#lbLoad').disabled=false;r.setUpdate(frame);view.update(0);follow.update(model.players,0);if(paused||document.hidden||document.hasFocus?.()===false)pause(true,'Focus changed while loading');else r.pause(false);if(mode==='suite'&&!paused){suiteAccumulator=0;suite.lastImpulse=-1;if(suite.auto&&!graphics.caps.gpu)suite.queue=['low'];run=suiteRun(SUITE_STAGES[suite.index],graphics.settings,{...monitor.metadata(),weather:'day',workload:model.chamber||null});view.setWeather('day');$('#lbTouch').hidden=true;$('#lbBenchStatus').hidden=false;$('#lbMonitor').hidden=false;$('#lbTouchToggle').hidden=true;host.querySelector('.lb-stage')?.classList.toggle('lb-monitor-visible',true);}if(mode==='baseline'&&!paused)startBenchmark();if(mode==='tune'&&!paused)startForestTuning();
