 function cue(e){if(mode==='suite')return;if(e.type==='water')notify('Deep water — returned to your last lantern. Cross at the bridge.');if(e.type==='lantern')notify((model.lanterns||LANTERNS)[e.id].name+' restored');if(['lantern','finish'].includes(e.type))for(const[f,i]of [[523,0],[659,1],[784,2]])synth?.play({frequency:f,duration:.26,delay:i*.1,volume:.55});if(e.type==='talk')notify(model.message);if(e.type==='notice')notify('A sentinel spotted you — watch its wind-up.');if(e.type==='door')notify('Gate opening — both explorers can pass.');if(['attack','pulse','hit','dodge','defeat'].includes(e.type))synth?.play({frequency:{attack:160,pulse:650,hit:95,dodge:300,defeat:480}[e.type],duration:.1,type:e.type==='hit'?'triangle':'sine',slide:e.type==='pulse'?-.3:.3,volume:.22});if(e.type==='jump')synth?.play({frequency:180,duration:.08,type:'sine',volume:.15});}
