 function showChamberLoad(){if(model?.zoneId!=='chaos')return;const limits=chamberLimits(runtime.software),load=model.chamber,labels={characters:'Animated trail guides',enemies:'Active optional enemies',physics:'Physics crates',projectiles:'Non-damaging demo pulses',particles:'Energy motes',lights:'Additional dynamic lights',complexity:'Decorative complexity tiers'};dialog(`<p class="lb-eyebrow">CHAOS CHAMBER · LIVE WORKLOAD</p><h2>Turn it up. Bring it back.</h2><p>These are real scene objects, animated characters and AI. The monitor shows actual frame times and counts. This is an interactive workload, not a formal recorded benchmark. Optional enemies do not lock the objective gate.</p><div class="lb-fields">${Object.entries(limits).map(([key,max])=>`<label>${labels[key]}<input type="range" data-load="${key}" min="0" max="${max}" step="1" value="${load[key]}" ${max===0?'disabled':''}><output data-load-value="${key}">${load[key]} / ${max}</output></label>`).join('')}</div><p class="lb-note">${runtime.software?'Compatibility caps are reduced; extra dynamic lights are unavailable.':'Start small and watch the measured frame monitor.'} Use Settings for draw distance, resolution and supported visual effects. Pause stops the workload. Reset immediately removes optional actors/effects and restores eight crates.</p>${chamberHistory.length?`<h3>Measured windows · this session</h3><table><thead><tr><th>Guides / AI / crates</th><th>Resolution</th><th>Frames</th><th>AVG / 1% FPS</th></tr></thead><tbody>${chamberHistory.map(run=>`<tr><td>${run.actual.characters} / ${run.actual.enemies} / ${run.actual.physics}</td><td>${run.metadata.renderWidth}×${run.metadata.renderHeight}</td><td>${run.metrics.frames}</td><td>${fmt(run.metrics.averageFPS)} / ${fmt(run.metrics.onePercentLowFPS)}</td></tr>`).join('')}</tbody></table>`:''}<p class="lb-note">Snapshots use the measured rolling window since the last load change, with renderer/resolution and actual counts. They are not controlled formal runs; history is temporary and capped at eight. Export before leaving.</p><button id="lbLoadSnapshot">CAPTURE MEASURED WINDOW</button><button id="lbLoadExport" ${chamberHistory.length?'':'disabled'}>EXPORT LOAD SNAPSHOTS</button><button id="lbLoadApply" class="lb-primary">APPLY LOAD & RETURN</button><button id="lbLoadReset">RESET LOAD NOW</button><button id="lbLoadClose">CANCEL</button>`,()=>{host.querySelectorAll('[data-load]').forEach(control=>control.oninput=()=>{host.querySelector('[data-load-value="'+control.dataset.load+'"]').textContent=control.value+' / '+limits[control.dataset.load];});$('#lbLoadApply').onclick=()=>applyChamberLoad(Object.fromEntries([...host.querySelectorAll('[data-load]')].map(control=>[control.dataset.load,+control.value])));$('#lbLoadReset').onclick=()=>applyChamberLoad(CHAMBER_DEFAULTS);$('#lbLoadSnapshot').onclick=()=>{if(!captureChamber())notify('Play a moment to collect real frame samples first.');showChamberLoad();};$('#lbLoadExport').onclick=()=>download(new Blob([JSON.stringify({scope:'Interactive Chamber measured windows; not a repeatable formal benchmark',runs:chamberHistory},null,2)],{type:'application/json'}),'Project-Limit-Break-Chamber-snapshots.json');$('#lbLoadClose').onclick=()=>{closeDialog();pause(false);};});}
 function complete(){if(mode==='journey'){completeJourneyArea();return;}committed=true;const s=model.summary();for(const id of ids.slice(0,players)){commitRound([{id,score:s.score,hits:3,errors:s.retries+s.defeats,details:{lanterns:s.lanterns,sentinels:s.sentinels,defeats:s.defeats},completed:true,elapsed:s.elapsed,duration:s.elapsed,soloWin:true}],{game:'limit',difficulty:3,learn:false,mode:'solo',ruleset:'limit-forest-v2',levelId:1,competition:players===2?'coop':'solo',challengeKey:'forest-2',seed:model.seed});unlock(player(id),'limit-first');unlock(player(id),'limit-sentinels');if(players===2)unlock(player(id),'limit-team');}save();dialog(`<p class="lb-eyebrow">CHAPTER COMPLETE · ${fmt(s.elapsed)} SECONDS</p><h2>The way is open.</h2><p>Three lanterns restored. Three sentinels defeated.<br>${s.retries} water recoveries · ${s.defeats} combat recoveries.<br>${s.score} points saved for ${ids.slice(0,players).map(id=>esc(player(id).name)).join(' + ')}.</p><button id="lbAgain" class="lb-primary">EXPLORE AGAIN</button><button id="lbBenchFromWin">RUN THE FOREST BASELINE</button><button id="lbReturn">ARCADE</button>`,()=>{$('#lbAgain').onclick=()=>launch('adventure');$('#lbBenchFromWin').onclick=()=>launch('baseline');$('#lbReturn').onclick=leave;});}

 function beginSuite(auto=false){suite={index:0,parts:[],auto,queue:graphics?.caps.gpu===false?['low']:['low','medium','high','ultra','maximum'],presetIndex:0,results:[],target};if(auto)preset='low';storePreferences();return launch('suite');}
 function frameSuite(dt,info){
  const stage=SUITE_STAGES[suite.index];
  run.frame(info.frameMs);const progress=run.elapsed<run.warmup?run.elapsed/run.warmup:Math.min(1,run.recorded/stage.seconds);
  suiteCamera(runtime,stage,progress);suiteAccumulator+=Math.min(.1,dt);
  while(suiteAccumulator>=1/60){view.syncCollision?.();suiteStep(model,1/60);suiteAccumulator-=1/60;}
  if(stage.zone==='chaos'&&Math.floor(model.clock)!==suite.lastImpulse){suite.lastImpulse=Math.floor(model.clock);for(const [i,prop]of view.props.entries())prop.body.body.applyImpulse(new runtime.B.Vector3(i%2?.25:-.25,2,0),prop.mesh.getAbsolutePosition());}view.update(dt);$('#lbBenchStatus').textContent=`${suite.auto?'SETTINGS TEST':'FIVE-WORLD SUITE'} · ${stage.name} · ${run.elapsed<run.warmup?'WARM-UP':Math.round(progress*100)+'%'}`;
  if((info.wallTime||performance.now())-lastHUD>250){lastHUD=info.wallTime||performance.now();hud();}
  if(!run.done)return;
  run.metadata.actual=monitor.snapshot({characters:view.characters});run.metadata.simulationSeconds=model.clock;run.metadata.simulationPolicy='60 Hz fixed steps, wall delta capped at 100 ms per rendered frame';suite.parts.push(run.result());run=null;suite.index++;
  if(suite.index<SUITE_STAGES.length){launch('suite');return;}
  const result=suiteResult(suite.parts);
  if(suite.auto){suite.results.push({preset,report:{averageFPS:Math.min(...result.stages.map(s=>s.averageFPS)),onePercentLowFPS:Math.min(...result.stages.map(s=>s.onePercentLowFPS)),p95Ms:Math.max(...result.stages.map(s=>s.p95Ms))}});suite.presetIndex++;
   if(suite.presetIndex<suite.queue.length){preset=suite.queue[suite.presetIndex];suite.index=0;suite.parts=[];launch('suite');return;}
   const recommendation=recommendPreset(suite.results,suite.target);preset=recommendation.preset;storePreferences();pause(true);
   dialog(`<h2>Your measured settings</h2><p>${recommendation.metTarget?'Recommended '+esc(GRAPHICS_PRESETS[preset].label)+' for '+recommendation.target+' FPS.':recommendation.target+' FPS was not sustained. Low is selected; manual overrides remain available.'}</p><p>Each preset used all five scenarios. Every scenario must meet the average, 1% low and p95 thresholds. These short tests cannot guarantee performance on every adventure path.</p><button id="lbTuneDone">RETURN TO SETUP</button>`,()=>$('#lbTuneDone').onclick=setup);return;
  }
  lastResult={...result,id:uid(),at:Date.now()};DB.settings.limitBreak={...(DB.settings.limitBreak||{}),preset,history:[...history(),lastResult].slice(-20)};save();pause(true);showSuiteResult(lastResult);
 }
 function showSuiteResult(r){dialog(`<p class="lb-eyebrow">FIVE-WORLD SUITE · ${esc(SUITE_EDITION)}</p><h2>${fmt(r.overall.averageFPS)} AVERAGE FPS</h2><p>1% low ${fmt(r.overall.onePercentLowFPS)} FPS · median ${fmt(r.overall.medianMs)} ms · p95 ${fmt(r.overall.p95Ms)} ms · spikes &gt;50 ms: ${r.overall.spikes}</p><p>${esc(r.metadata.renderer)} · ${r.metadata.renderWidth}×${r.metadata.renderHeight} · ${esc(r.settings.label)} · ${r.overall.frames} measured frames</p><table><thead><tr><th>Scenario</th><th>AVG / 1% FPS</th><th>p95 ms</th></tr></thead><tbody>${r.stages.map(s=>`<tr><td>${esc(s.name)}</td><td>${fmt(s.averageFPS)} / ${fmt(s.onePercentLowFPS)}</td><td>${fmt(s.p95Ms)}</td></tr>`).join('')}</tbody></table><p>Three-second warm-up per scene; loading excluded. Seeded fixed-step scripted actors and fixed camera paths; physics/backend scheduling may vary. No adaptive quality. GPU/RAM/VRAM values are not estimated. Software rendering does not predict Windows performance. Fewer than 100 frames per scenario limits 1% low confidence.</p><button id="lbSuiteJSON">EXPORT JSON + RAW FRAMES</button><button id="lbSuiteCSV">EXPORT CSV</button><button id="lbSuiteHistory">COMPARE RUNS</button><button id="lbSuiteAgain">RUN AGAIN</button><button id="lbSuiteClose">RETURN TO SETUP</button>`,()=>{$('#lbSuiteJSON').onclick=()=>download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),'Limit-Break-suite-'+r.id+'.json');$('#lbSuiteCSV').onclick=()=>download(new Blob([suiteCSV(r)],{type:'text/csv'}),'Limit-Break-suite-'+r.id+'.csv');$('#lbSuiteHistory').onclick=showHistory;$('#lbSuiteAgain').onclick=()=>beginSuite();$('#lbSuiteClose').onclick=setup;});}
 function startBenchmark(stages=FOREST_BENCHMARK_STAGES,warmup=5){run=new BenchmarkRun({stages,warmup,seed:model.seed,settings:graphics.settings,metadata:{...monitor.metadata(),baseline:'living-forest-v2-navigation',scope:'Milestone 2 forest traversal, obstacle-aware wardens and physics; no castle/combat stress/chaos results',characters:view.characters,weather:'day',physicsObjects:view.props.length,audio:'No ambience during baseline',adaptiveQuality:false,warmupPath:'One pre-recording sweep of all forest stages'}});view.setWeather('day');view.resetPhysics();$('#lbTouch').hidden=true;$('#lbBenchStatus').hidden=false;$('#lbPauseCard').hidden=true;paused=false;runtime.pause(false);$('#lbMonitor').hidden=false;$('#lbTouchToggle').hidden=true;host.querySelector('.lb-stage')?.classList.toggle('lb-monitor-visible',true);}
