 async function switchToMeasurement(requested){if(mode==='journey'&&journey&&!journey.done&&!await ask('Leave the expedition for measurements?','This unfinished expedition will restart from the Forest. No partial score will be saved.'))return;if(requested==='suite-start')return beginSuite();if(requested==='suite-tune')return beginSuite(true);return launch(requested);}
 function showSettings(){const caps=graphics.caps,s=graphics.settings;dialog(`<p class="lb-eyebrow">GRAPHICS & PERFORMANCE</p><h2>Make this world yours.</h2><p>${caps.renderer}. ${caps.gpu?'Effects are limited to reported capabilities.':'Compatibility mode uses reduced geometry/distance and texture sampling. GPU effects are unavailable.'}</p><div class="lb-fields"><label>Preset<select id="lbLivePreset">${presets()}</select></label><label>Resolution scale<select id="lbScale">${[.5,.7,.9,1,1.15,1.25].map(v=>`<option ${v===s.resolutionScale?'selected':''}>${v}</option>`).join('')}</select></label><label>Surface textures<select id="lbTexture"><option value="low" ${s.texture==='low'?'selected':''}>512 px</option><option value="high" ${s.texture==='high'?'selected':''}>1024 px</option></select></label><label>View distance<input id="lbDistance" type="range" min="12" max="68" value="${s.distance}"></label><label>Foliage density<input id="lbFoliage" type="range" min=".2" max="1.7" step=".1" value="${s.foliage}"></label><label>Shadow map<select id="lbShadow" ${!caps.shadows?'disabled':''}>${[0,1024,2048,4096].map(v=>`<option ${v===s.shadowSize?'selected':''}>${v}</option>`).join('')}</select></label><label>Particle density<input id="lbParticles" type="range" min="0" max="220" value="${s.particles}"></label><label>Post-process MSAA<select id="lbMSAA" ${!caps.post?'disabled':''}>${[1,2,4].map(v=>`<option ${v===s.samples?'selected':''} ${v>caps.maxSamples?'disabled':''}>${v}</option>`).join('')}</select></label><label>Physics objects<input id="lbPhysics" type="range" min="0" max="48" value="${s.physics}"></label><label>Lighting / weather<select id="lbWeather"><option value="day">Day</option><option value="dusk">Dusk</option><option value="night">Night</option><option value="rain">Rain</option></select></label><label>Target FPS<select id="lbTarget"><option ${target===30?'selected':''}>30</option><option ${target===60?'selected':''}>60</option></select></label></div><fieldset class="lb-input-settings"><legend>CONTROLS & CAMERA</legend><div class="lb-fields"><label>Controller camera speed<input id="lbControllerLook" type="range" min="0.25" max="2" step="0.05" value="${inputPrefs.controllerLook}"><output data-input-value="lbControllerLook">${inputPrefs.controllerLook.toFixed(2)}×</output></label><label>Camera stick deadzone<input id="lbLookDeadzone" type="range" min="0.1" max="0.4" step="0.01" value="${inputPrefs.lookDeadzone}"><output data-input-value="lbLookDeadzone">${Math.round(inputPrefs.lookDeadzone*100)}%</output></label><label>Touch camera speed<input id="lbTouchLook" type="range" min="0.25" max="2" step="0.05" value="${inputPrefs.touchLook}"><output data-input-value="lbTouchLook">${inputPrefs.touchLook.toFixed(2)}×</output></label><label>Touch controls<select id="lbTouchMode"><option value="auto" ${inputPrefs.touchControls==='auto'?'selected':''}>Auto · follow input</option><option value="show" ${inputPrefs.touchControls==='show'?'selected':''}>Always show</option><option value="hide" ${inputPrefs.touchControls==='hide'?'selected':''}>Hide · toolbar can restore</option></select></label></div><label class="lb-invert"><input id="lbInvertLook" type="checkbox" ${inputPrefs.invertY?'checked':''}>Invert controller/touch up/down</label><p class="lb-note">Drag the LOOK pad while moving with either movement stick. Auto retains touch controls for mixed-input co-op. Camera settings never change benchmark graphics or scores.</p></fieldset><div class="lb-checks">${[['ao','Ambient occlusion'],['reflections','Water reflections'],['post','Bloom / FXAA post-processing']].map(([key,label])=>`<label><input type="checkbox" data-effect="${key}" ${s[key]?'checked':''} ${!caps[key]?'disabled':''}>${label} ${!caps[key]?'· N/A':''}</label>`).join('')}</div><p class="lb-note">Imported model textures are fixed up to 1024 px. Surface quality changes terrain/bark maps. Formal runs hold all settings fixed. Five-world settings tuning takes about a minute per tested preset plus loading; pause cancels without saving a partial result. System RAM and VRAM readings are unavailable.</p><button id="lbApply" class="lb-primary">APPLY & RETURN</button><button id="lbTune">FIND MY BEST SETTINGS</button><button id="lbStartSuite">RUN FIVE-WORLD BENCHMARK</button><button id="lbStartBench">RUN 35-SECOND FOREST BASELINE</button><button id="lbSettingsClose">CANCEL</button>`,()=>{$('#lbApply').onclick=()=>{inputPrefs=forestInputSettings({controllerLook:+$('#lbControllerLook').value,touchLook:+$('#lbTouchLook').value,lookDeadzone:+$('#lbLookDeadzone').value,invertY:$('#lbInvertLook').checked,touchControls:$('#lbTouchMode').value});preset=$('#lbLivePreset').value;const over={resolutionScale:+$('#lbScale').value,texture:$('#lbTexture').value,distance:+$('#lbDistance').value,foliage:+$('#lbFoliage').value,physics:+$('#lbPhysics').value,particles:+$('#lbParticles').value,shadowSize:+$('#lbShadow').value,samples:+$('#lbMSAA').value};host.querySelectorAll('[data-effect]').forEach(e=>over[e.dataset.effect]=e.checked);const weather=$('#lbWeather').value;applySettings(over);view.setWeather(weather);closeDialog();pause(false);syncTouchControls();};$('#lbLivePreset').onchange=e=>{const draft=resolveGraphics(e.target.value,caps);for(const [id,key]of [['lbScale','resolutionScale'],['lbTexture','texture'],['lbDistance','distance'],['lbFoliage','foliage'],['lbShadow','shadowSize'],['lbParticles','particles'],['lbPhysics','physics'],['lbMSAA','samples']])$('#'+id).value=draft[key];host.querySelectorAll('[data-effect]').forEach(n=>n.checked=draft[n.dataset.effect]);};for(const id of ['lbControllerLook','lbTouchLook','lbLookDeadzone'])$('#'+id).oninput=e=>{host.querySelector('[data-input-value="'+id+'"]').textContent=id==='lbLookDeadzone'?Math.round(+e.target.value*100)+'%':(+e.target.value).toFixed(2)+'×';};$('#lbTarget').onchange=e=>target=+e.target.value;$('#lbSettingsClose').onclick=()=>{closeDialog();pause(false);};$('#lbStartSuite').onclick=()=>switchToMeasurement('suite-start');$('#lbStartBench').onclick=()=>switchToMeasurement('baseline');$('#lbTune').onclick=()=>switchToMeasurement('suite-tune');});}
 function showResult(r){if(r.metadata.baseline===SUITE_EDITION)return showSuiteResult(r);dialog(`<p class="lb-eyebrow">MEASURED FOREST BASELINE · ${esc(r.metadata.renderer)}</p><h2>${fmt(r.overall.averageFPS)} <small>AVERAGE FPS</small></h2><div class="lb-result-grid"><span><b>${fmt(r.overall.onePercentLowFPS)}</b>1% LOW FPS</span><span><b>${fmt(r.overall.medianMs)} ms</b>MEDIAN FRAME</span><span><b>${fmt(r.overall.p95Ms)} ms</b>p95 FRAME</span><span><b>${fmt(r.overall.worstMs)} ms</b>WORST FRAME</span></div><p>${esc(r.settings.label)} · ${r.metadata.renderWidth}×${r.metadata.renderHeight} · ${r.overall.frames} frames<br>Babylon.js 9.32.0 / Havok 1.3.14 · ${r.settings.ao?'AO on':'AO off'} · ${r.settings.reflections?'planar reflections':'reflections off'}</p><table><thead><tr><th>Forest stage</th><th>AVG FPS</th><th>1% LOW</th><th>p95 ms</th></tr></thead><tbody>${r.stages.map(s=>`<tr><td>${esc(s.name)}</td><td>${fmt(s.averageFPS)}</td><td>${fmt(s.onePercentLowFPS)}</td><td>${fmt(s.p95Ms)}</td></tr>`).join('')}</tbody></table><p class="lb-note">${r.overall.sampleLimited?'Fewer than 100 frames were captured; 1% lows use a small sample. ':''}This is the forest traversal baseline; its edition is ${esc(r.metadata.baseline||'living-forest-v1')}. Compare runs from the same edition. It is not a combat stress test. Software results do not predict Windows GPU performance. No synthetic score, RAM estimate or VRAM estimate is shown.</p><button id="lbResultPlay" class="lb-primary">PLAY THE FOREST</button><button id="lbJSON">EXPORT JSON</button><button id="lbCSV">EXPORT CSV</button><button id="lbCompare">COMPARE RUNS</button><button id="lbRerun">RUN AGAIN</button><button id="lbResultExit">BACK TO ARCADE</button>`,()=>{$('#lbResultPlay').onclick=()=>launch('adventure');$('#lbJSON').onclick=()=>download(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}),'Project-Limit-Break-forest-'+r.id+'.json');$('#lbCSV').onclick=()=>download(new Blob([benchmarkCSV(r)],{type:'text/csv'}),'Project-Limit-Break-forest-'+r.id+'.csv');$('#lbCompare').onclick=showHistory;$('#lbRerun').onclick=()=>launch('baseline');$('#lbResultExit').onclick=()=>{disposeScene();exit();};});}
 function showAdventureRecords(edition=DB.profiles.some(p=>p.results?.some(r=>r.ruleset==='limit-expedition-v1'))?'limit-expedition-v1':'limit-forest-v2',competition='solo'){const rows=adventureRecordRows(DB.profiles,edition,competition);dialog(`<p class="lb-eyebrow">COMPLETED ADVENTURES · SEPARATE EDITIONS</p><h2>The paths you’ve taken.</h2><div class="lb-fields"><label>Adventure<select id="lbRecordEdition">${[['limit-expedition-v1','Four-area expedition'],['limit-forest-v2','Forest combat chapter'],['limit-forest-v1','Original Forest chapter']].map(([id,name])=>`<option value="${id}" ${id===edition?'selected':''}>${name}</option>`).join('')}</select></label><label>Team<select id="lbRecordTeam"><option value="solo" ${competition==='solo'?'selected':''}>Solo</option><option value="coop" ${competition==='coop'?'selected':''}>Co-op</option></select></label></div><p>Best completed result per player in this edition and team mode. Forest chapter points are never compared with the longer expedition.</p>${rows.length?`<table><thead><tr><th>Player</th><th>Points</th><th>Active time</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.profile.name)}</td><td>${row.result.score}</td><td>${fmt(row.result.elapsed)} s</td></tr>`).join('')}</tbody></table>`:'<p>No completed runs in this selection yet.</p>'}<button id="lbOpenBenchHistory">MEASURED BASELINE HISTORY</button><button id="lbRecordsClose" class="lb-primary">CLOSE</button>`,()=>{$('#lbRecordEdition').onchange=e=>showAdventureRecords(e.target.value,competition);$('#lbRecordTeam').onchange=e=>showAdventureRecords(edition,e.target.value);$('#lbOpenBenchHistory').onclick=showHistory;$('#lbRecordsClose').onclick=closeDialog;});}
 function showHistory(){dialog(`<p class="lb-eyebrow">DEVICE-LOCAL HISTORY · ${history().length} / 20 RUNS</p><h2>Compare the evidence.</h2><p>Compare renderer, resolution and settings before drawing conclusions. Forest baselines and five-world suites are separate editions. Rows marked comparable match edition, seed, renderer, browser, resolution and settings; different devices and background load can still differ. Separate from adventure scores.</p>${history().length?`<table><thead><tr><th>Run</th><th>Renderer / preset</th><th>Resolution</th><th>AVG / 1% FPS</th><th>AVG difference vs latest matching run</th></tr></thead><tbody>${history().slice().reverse().map((r,i)=>`<tr><td><button data-result="${esc(r.id)}">${new Date(r.at).toLocaleString()}</button></td><td>${esc(r.metadata.baseline)} · ${esc(r.metadata.renderer)} / ${esc(r.settings.label)} ${history().length>1&&comparisonKey(r)===comparisonKey(history().at(-1))?'· comparable to latest':''}</td><td>${r.metadata.renderWidth}×${r.metadata.renderHeight}</td><td>${fmt(r.overall.averageFPS)} / ${fmt(r.overall.onePercentLowFPS)}</td><td>${history().filter(other=>other.id!==r.id&&comparisonKey(other)===comparisonKey(r)).at(-1)?fmt(r.overall.averageFPS-history().filter(other=>other.id!==r.id&&comparisonKey(other)===comparisonKey(r)).at(-1).overall.averageFPS)+' FPS':'N/A'}</td></tr>`).join('')}</tbody></table>`:'<p>No measurements yet. Run the automatic Forest Baseline to record actual frames.</p>'}<button id="lbHistoryClose" class="lb-primary">CLOSE</button>`,()=>{host.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>showResult(history().find(r=>r.id===b.dataset.result)));$('#lbHistoryClose').onclick=()=>closeDialog();});}
 function padContext(){const background=document.hidden||document.hasFocus?.()===false,native=document.querySelector?.('dialog[open]'),custom=$('#lbDialog')&&!$('#lbDialog').hidden?$('#lbDialog'):null,loading=page==='play'&&$('#lbLoading')&&!$('#lbLoading').hidden,error=loading&&!!$('#lbRetry');return{key:page+':'+(background?'background':native?'instructions':custom?'dialog':error?'error':loading?'loading':paused?'pause':run?'baseline':'play'),mode:background?'background':native||custom||error||page!=='play'||paused?'menu':loading?'loading':run?'baseline':'game',surface:native||custom||host,canPause:!background&&page==='play'&&!!view&&!native&&!custom};}
 const padUI=createControllerUI({root:host,hub,getContext:padContext,onPause:()=>paused&&!playable()?launch('adventure'):pause(!paused),onBack:()=>{const native=document.querySelector?.('dialog[open]');if(native){native.querySelector('[data-instructions-back]')?.click();return;}if(!$('#lbDialog')?.hidden){if(mode==='journey'&&model?.done&&committed){($('#lbNextZone')||$('#lbJourneyReturn'))?.focus();return;}const close=$('#lbGuideClose')||$('#lbSettingsClose')||$('#lbHistoryClose')||$('#lbLoadClose')||$('#lbRecordsClose');if(close)close.click();else closeDialog();return;}if(paused)playable()?pause(false):launch('adventure');else if(page==='setup')leave();},onHelp:()=>gate.review(),onCenter:i=>{const p=model?.players[i];if(p&&runtime){runtime.camera.alpha=-Math.PI/2-p.angle;runtime.camera.beta=1.23;}},onLook:(i,x,y,dt)=>{if(runtime&&!paused&&!run&&i<model.players.length)rotateForestCamera(runtime.camera,x,y,dt*2.2*inputPrefs.controllerLook,dt*1.4*inputPrefs.controllerLook,inputPrefs.invertY);},getLookDeadzone:()=>inputPrefs.lookDeadzone,onActivity:()=>{lastInput='controller';syncTouchControls();},onStatus:text=>{const status=$('#lbPadStatus');if(status&&status.textContent!==text)status.textContent=text;syncTouchControls();}});
 const visibility=()=>{if(document.hidden&&page==='play')pause(true,'Tab hidden');};document.addEventListener('visibilitychange',visibility);const resize=()=>{if(run){pause(true,'Viewport resized');if($('#lbBenchStatus'))$('#lbBenchStatus').textContent='Benchmark stopped after resize. Run again at a fixed resolution.';}};window.addEventListener('resize',resize);const blur=()=>{if(page==='play')pause(true,'Window unfocused');};window.addEventListener('blur',blur);setup();if(initialPage==='records')showAdventureRecords();return()=>{disposed=true;host.removeEventListener?.('pointerdown',touchStart,true);window.removeEventListener('pointerup',touchEnd);window.removeEventListener('pointercancel',touchEnd);padUI.dispose();disposeScene();gate.dispose();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('resize',resize);window.removeEventListener('blur',blur);};
